19	    public SecurityConfig(ApiKeyFilter apiKeyFilter) {
20	        this.apiKeyFilter = apiKeyFilter;
21	    }
22	
23	    @Bean
24	    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
25	        http
26	                .csrf(csrf -> csrf.disable())
27	                .cors(Customizer.withDefaults())
28	                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
29	                .authorizeHttpRequests(auth -> auth
30	                        .requestMatchers("/api/v1/api-keys/**", "/actuator/health", "/docs/**", "/api-docs/**", "/swagger-ui/**", "/ws/**").permitAll()
31	                        .anyRequest().authenticated()
32	                )
33	                .addFilterBefore(apiKeyFilter, UsernamePasswordAuthenticationFilter.class);
34	        return http.build();
35	    }
36	}

